identifier, unique within its community. A closed alphabet: it appears in the ticket class label `voter/<electionId>` and is framed into every hash a cast is bound to.","type":"string","pattern":"^[A-Za-z0-9._-]{1,128}\$"},"DigestMultibase":{"title":"DigestMultibase","description":"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\"interoperability is not guaranteed between implementations using such values\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]},"EncryptedCast":{"title":"EncryptedCast","description":"A cast of a sealed or tallied-encrypted election: exactly one of `sealed` (the Ballot\'s JCS bytes sealed to the election key) or `encrypted`, with the tag and the attestation over the JCS bytes of whichever is present (CONVENTIONS §3.6, §9.5).","type":"object","additionalProperties":false,"required":["tag","attestation"],"properties":{"sealed":{"\$ref":"#/\$defs/SealedPayload"},"encrypted":{"\$ref":"#/\$defs/EncryptedBallot"},"tag":{"\$ref":"#/\$defs/Multibase"},"attestation":{"\$ref":"#/\$defs/Multibase"}},"oneOf":[{"required":["sealed"]},{"required":["encrypted"]}]},"EncryptedBallot":{"title":"EncryptedBallot","description":"A tallied-encrypted ballot: one EncryptedQuestion per manifest question, in the manifest\'s order. Never decrypted (VTI-VOT-064).","type":"object","additionalProperties":false,"required":["electionId","manifestDigest","questions"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"manifestDigest":{"\$ref":"#/\$defs/DigestMultibase"},"questions":{"type":"array","minItems":1,"maxItems":64,"items":{"\$ref":"#/\$defs/EncryptedQuestion"}}}},"EncryptedQuestion":{"title":"EncryptedQuestion","description":"One choice question of a tallied-encrypted ballot: per option, in the manifest\'s order, an encryption of 0 or 1 with its proof; and a proof that the selections sum to a count the question admits (CONVENTIONS §9.5).","type":"object","additionalProperties":false,"required":["question","options","sumProof"],"properties":{"question":{"\$ref":"#/\$defs/Key"},"options":{"type":"array","minItems":1,"maxItems":64,"items":{"\$ref":"#/\$defs/EncryptedOption"}},"sumProof":{"\$ref":"#/\$defs/DisjunctiveProof"}}},"DisjunctiveProof":{"title":"DisjunctiveProof","description":"A disjunctive proof that a ciphertext encrypts one value of a public list: one `(c, z)` per value, in the list\'s order (CONVENTIONS §9.3).","type":"array","minItems":1,"maxItems":65,"items":{"\$ref":"#/\$defs/SigmaProof"}},"SigmaProof":{"title":"SigmaProof","description":"A non-interactive sigma proof as its challenge and response `(c, z)` (Schnorr or Chaum–Pedersen; CONVENTIONS §9.3).","type":"object","additionalProperties":false,"required":["c","z"],"properties":{"c":{"\$ref":"#/\$defs/GroupScalar"},"z":{"\$ref":"#/\$defs/GroupScalar"}}},"GroupScalar":{"title":"GroupScalar","description":"A scalar mod the Ristretto group order: 32 canonical little-endian bytes, multibase base58btc (CONVENTIONS §9.1).","type":"string","minLength":2,"maxLength":64,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"},"EncryptedOption":{"title":"EncryptedOption","type":"object","additionalProperties":false,"required":["ciphertext","proof"],"properties":{"ciphertext":{"\$ref":"#/\$defs/ElGamalCiphertext"},"proof":{"\$ref":"#/\$defs/DisjunctiveProof"}}},"ElGamalCiphertext":{"title":"ElGamalCiphertext","description":"`(a, b) = (r·G, M + r·Y)` under the election key `Y` (CONVENTIONS §9.2).","type":"object","additionalProperties":false,"required":["a","b"],"properties":{"a":{"\$ref":"#/\$defs/GroupElement"},"b":{"\$ref":"#/\$defs/GroupElement"}}},"GroupElement":{"title":"GroupElement","description":"A Ristretto group element: its 32-byte compression, multibase base58btc. Never the identity (CONVENTIONS §9.1).","type":"string","minLength":2,"maxLength":64,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"},"Key":{"title":"Key","description":"A question or option key, unique within its manifest or question.","type":"string","pattern":"^[A-Za-z0-9._-]{1,64}\$"},"SealedPayload":{"title":"SealedPayload","description":"Bytes sealed to a key: a random group element encrypted as `kem`, and the bytes under ChaCha20-Poly1305 with a key derived from it, multibase base58btc (CONVENTIONS §9.4).","type":"object","additionalProperties":false,"required":["kem","body"],"properties":{"kem":{"\$ref":"#/\$defs/ElGamalCiphertext"},"body":{"type":"string","minLength":2,"maxLength":131072,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"}}}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
